using System;

public struct Quote
{
    public string Id;
    public string Text;
    public string Author;
}

public static class FrenchQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaoru_Mori", Text = "C'est vrai que je devrais passer deux semaines par épisode… Mais en réalité, il me faut souvent un mois.", Author = "Kaoru Mori" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Elio_Di_Rupo", Text = "J’en ai marre des parvenus! Il n’y a pas de place pour les parvenus au parti socialiste.", Author = "Elio Di Rupo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Charles_Chesnelong", Text = "Quand le mal a toutes les audaces, il faut que le bien ait tous les courages.", Author = "Charles Chesnelong" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9bat", Text = "Une société politique authentique, où la discussion et les débats sont une technique essentielle, est une société pleine de risques.", Author = "Débat" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Patrick_Devedjian", Text = "J'ai rassemblé des gens qui m'étaient hostiles.", Author = "Patrick Devedjian" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Corps_de_mon_ennemi", Text = "Pendant qu'une saine jeunesse agite des calicots, elle ne brandit pas de pancarte.", Author = "Le Corps de mon ennemi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Florence_Chitacumbi", Text = "Les Chinois sont ouverts à toutes sortes de styles de musique, y compris la musique francophone. On sent qu'ils ont été longtemps bridés et qu'ils ont envie de découvrir de nouvelles choses.", Author = "Florence Chitacumbi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vincent_Message", Text = "Est-ce que les hommes s'en voulaient, eux, de saloper la planète au nom de leurs appétits prétendument inextinguibles? Certains, sûrement, un peu, mais combien à vrai dire? Combien se sentaient responsables? Combien acceptaient de limiter leurs désirs? Combien n'en dormaient plus la nuit?", Author = "Vincent Message" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nafissatou_Id%C3%A9_Sadou", Text = "Pour finir, je dirai que tant que les droits des femmes ne connaitront pas un véritable essor au Niger, mes projets seront toujours orientés dans ce sens, notamment en ce qui concerne l’éducation et la formation de la junte féminine.", Author = "Nafissatou Idé Sadou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Simone_Gbagbo", Text = "Nous sommes dans une conflictualité larvée et dans une bataille de positionnement stratégique qui ne dit pas son nom parce que ce positionnement répond à une volonté proactive d’exister.", Author = "Simone Gbagbo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Magdalena_Abakanowicz", Text = "Une foule d'hommes ou d'oiseaux, d'insectes ou de feuilles est un assemblage mystérieux de variantes de certains prototypes.", Author = "Magdalena Abakanowicz" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/H%C3%A9lie_de_Saint_Marc", Text = "Je me répétais: Si on doit un jour ne plus comprendre comment un homme a pu donner sa vie pour quelque chose qui le dépasse, ce sera fini de tout un monde, peut-être de toute une civilisation.", Author = "Hélie de Saint Marc" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Netumbo_Nandi-Ndaitwah", Text = "Je n’ai pas été élue parce que je suis une femme, mais parce que j’en suis capable.", Author = "Netumbo Nandi-Ndaitwah" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wole_Soyinka", Text = "Si les morts ne sont pas assez forts pour être sans cesse présents en nous, ne doivent-ils pas être ce qu’ils sont, morts?", Author = "Wole Soyinka" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jerzy_Popie%C5%82uszko", Text = "Il ne faut pas s'incliner devant les circonstances et laisser les vérités derrière la porte. Il ne faut pas s'incliner devant les circonstances...", Author = "Jerzy Popiełuszko" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Titica", Text = "Je ne pense pas que mes chansons pourront complètement changer les mentalités", Author = "Titica" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27%C3%89vangile_selon_Pilate", Text = "La souffrance n’est pas une occasion de haïr, c’est une occasion d’aimer.\nC’est la seule chose que nous apprend la mort: qu’il est urgent d’aimer.\nRien ne supprime le chagrin; mais le vrai cœur le rend utile et bénéfique.", Author = "L'Évangile selon Pilate" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coco_Chanel", Text = "J’ai rendu au corps des femmes sa liberté; ce corps suait dans des habits de parade, sous les dentelles, les corsets, les dessous, le rembourrage.", Author = "Coco Chanel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/A%C3%AFcha_Mama_Kane", Text = "Réussir ne signifie pas seulement aller à l'école. Beaucoup de personnes ont réussi dans d'autres secteurs, alors qu'ils n'ont pas eu besoin de faire les bancs.", Author = "Aïcha Mama Kane" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Green", Text = "Hazel Grace Lancaster: Je suis tombée amoureuse pendant qu'il lisait, comme on s'endort: d'abord doucement et puis tout d'un coup.", Author = "John Green" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Madame_Ulrich", Text = "Merlin: L'impatience la plus violente n'avance pas une affaire du moindre petit moment.", Author = "Madame Ulrich" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-C%C3%A9lie_Agnant", Text = "La haine, c’est comme une odeur de brûlé ou de pourri. Il n’est pas facile de la maquiller.", Author = "Marie-Célie Agnant" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Rochefort", Text = "C’est  Harold Pinter, cet ami Nobel, compagnon du whisky, qui, dans son théâtre et dans sa vie, écrivait ou disait souvent: ‘’Ce genre de choses’’.", Author = "Jean Rochefort" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ambrose_Bierce", Text = "Abstinent: personne faible qui cède à la tentation de se refuser un plaisir.", Author = "Ambrose Bierce" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Magufuli", Text = "Il est honteux de dépenser  de l’ argent pour célébrer l’indépendance quand le peuple meurt de choléra.", Author = "John Magufuli" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sac_d%27os", Text = "Quand on gagne son pain quotidien en labourant les terres de l'imaginaire, la ligne qui sépare ce qui est de ce qui semble être est encore plus ténue.", Author = "Sac d'os" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Emmanuel_Levinas", Text = "On conviendra aisément qu’il importe au plus haut point de savoir si l’on n’est pas dupe de la morale.", Author = "Emmanuel Levinas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alejandra_Pizarnik", Text = "les jours te rongent\nles nuits t’accusent\nla vie te fait tant tant de mal\ndésespérée, où vas-tu?\ndésespérée, c’est tout!", Author = "Alejandra Pizarnik" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Horde_sauvage", Text = "S'ils font un mouvement, tuez-les!", Author = "La Horde sauvage" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Tumba_Nzeza", Text = "La Haine n’a jamais construit. Bien au contraire, elle détruit tout et en définitive, elle tue.", Author = "Marie Tumba Nzeza" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Antonio_Gramsci", Text = "La crise consiste justement dans le fait que l’ancien meurt et que le nouveau ne peut pas naître: pendant cet interrègne on observe les phénomènes morbides les plus variés.", Author = "Antonio Gramsci" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Festival_de_Cannes", Text = "Couronnez un Américain, vous êtes vendus à l'Amérique. Couronnez un Russe, vous êtes communiste. On n'en finirait plus de chercher le dessous des cartes. C'est la structure profonde du Festival qui est mauvaise, c'est elle qu'il importe de changer.", Author = "Festival de Cannes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alain-G%C3%A9rard_Slama", Text = "Vous avez des femmes qui pour arrondir leur fin de mois, se vendent pour quelques heures. Que ce soit triste, d’accord, mais c’est leur problème, ce n’est pas le nôtre", Author = "Alain-Gérard Slama" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Arnaud_Montebourg", Text = "Ségolène Royal n'a qu'un seul défaut, c'est son compagnon.", Author = "Arnaud Montebourg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9m%C3%A9trios_de_Phal%C3%A8re", Text = "Les livres ont plus de courage que les courtisans pour dire la vérité aux rois.", Author = "Démétrios de Phalère" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rebecca_Miano", Text = "Le succès, c’est aller au-delà de certaines attentes avec l’excellence, non pas la perfection, mais avec l’excellence. Parce que l’excellence, c’est quand on fait toujours quelque chose de bien. J’ai fait la différence avec excellence. Et je pense que j’ai brisé les limites.", Author = "Rebecca Miano" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maigret_tend_un_pi%C3%A8ge_%28film%29", Text = "En fin de compte, ces femmes-là trouvent toujours preneur. Tout le monde visite et un imbécile finit par acheter.", Author = "Maigret tend un piège (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wall_Street", Text = "Marvin: Mais ça pourrait-être bien pire que ça… Ça pourrait être mon fric! Ah ah ah ah.", Author = "Wall Street" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Piotr_Rosinski", Text = "Je suis le gardien de la cohérence graphique de Thorgal, tellement complexe.", Author = "Piotr Rosinski" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ak%C3%A9_Loba", Text = "Les dieux faisant un tri parmi les hommes, éliminent les pires et les meilleurs, ne laissant vieillir que les rares mortels qui ont vécu sans haine et sans excès pour qu'ils conduisent la génération suivante.", Author = "Aké Loba" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louise_Arbour", Text = "Le Conseil de sécurité pouvait m'arrêter, il pouvait gracier Milošević. Il pouvait faire tout ce qu'il voulait s'il estimait qu'une action de ma part risquait de déclencher la Troisième Guerre mondiale. C'était son problème, pas le mien.", Author = "Louise Arbour" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Valentine_Rugwabiza", Text = "nous avons réellement réalisé des progrès significatifs, même si nous n’en sommes pas encore là. Nous n’avons donc pas l’intention de nous reposer sur nos réalisations passées, car nous savons que cela ne suffit pas.", Author = "Valentine Rugwabiza" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Duke_Nukem", Text = "Il est temps de botter des culs et de mâcher du chewing-gum, et je n'ai plus de chewing gum!", Author = "Duke Nukem" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bibiane_Ou%C3%A9draogo_Boni", Text = "Le vrai bonheur d’une famille réside dans la stabilité, la confiance, le respect et la communication.", Author = "Bibiane Ouédraogo Boni" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Alfred_Korzybski", Text = "La structure de toute chose, qu'il s'agisse d'un langage, d'une maison, d'une machine, etc., se résume à des relations. Pour qu'il y ait structure, il doit y avoir tout un complexe ou réseau de parties ordonnées et reliées entre elles.", Author = "Alfred Korzybski" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Albert_R%C3%B6sti", Text = "[…] l'accord conclu avec l'UE sur la libre circulation des personnes accorde à plus de 500 millions de citoyens de l'UE le droit d'immigrer et de s'établir en Suisse. Hormis la Suisse, aucun État indépendant du monde n'a signé un tel accord avec presque un continent entier.", Author = "Albert Rösti" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Brian_May", Text = "Nous allons te (ou vous) secouer", Author = "Brian May" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andrew_Auernheimer", Text = "Je pense qu'il est mal jugé par le public. Je ne veux pas dire qu'ils lui ont tendu un piège mais il semble que cette histoire recèle plus qu'elle n'y paraît.", Author = "Andrew Auernheimer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Boris_Cyrulnik", Text = "Tout organisme pour s'adapter doit innover, tenter une aventure hors de la norme, engendrer de l'anormalité afin de voir si ça marche, car vivre, c'est prendre un risque.", Author = "Boris Cyrulnik" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Blaise_de_Monluc", Text = "Sans les escriptures qui se font parmy le monde, la pluspart des gens d'honneur ne se soucieroient d'acquerir de la reputation, car elle couste trop cher.", Author = "Blaise de Monluc" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gilles_Archambault", Text = "Depuis quelques années, je n'attend rien d'autre de la vie que des mots.", Author = "Gilles Archambault" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aminata_Mbengue_Ndiaye", Text = "Si on me donne des conseils alors que je ne comprends rien et qu’au final ce sont les conseillers qui prennent les décisions à ma place, je n’ai pas besoin d’être ministre.", Author = "Aminata Mbengue Ndiaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marcus_Furius_Camillus", Text = "Pas avec l'or mais avec le fer, on rachète la patrie.", Author = "Marcus Furius Camillus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Manteau", Text = "Ils déplient leurs manteaux, ils étendent leurs cascades, ils dévoilent leurs profondeurs, transparence polie au feu — les bleus.", Author = "Manteau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Charles-Maurice_de_Talleyrand-P%C3%A9rigord", Text = "La fixité dans les natures composées tient à leur souplesse.", Author = "Charles-Maurice de Talleyrand-Périgord" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gr%C3%A2ce_d%27Almeida", Text = "En prenant l'initiative de mettre le guide judiciaire à la disposition des femmes, l'Association des femmes juristes a voulu doter les femmes du Bénin des procédures juridiques essentielles, ancrées dans le cadre juridique national, pour les aider à améliorer leur vie par des moyens légaux.", Author = "Grâce d'Almeida" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Franz_Bartelt", Text = "La distance reste un bon outil d'évaluation de l'orgueil. Le problème n'a jamais été d'aller quelque part, mais seulement d'aller aussi loin que possible.", Author = "Franz Bartelt" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fred_Vargas", Text = "Les idées c'est comme tout, on les retourne, on les use, et puis elles se trouent et c'est très triste si tu n'as pas moyen d'en changer.", Author = "Fred Vargas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roberto_Saviano", Text = "Aucune autre idéologie, nul symbole ou forme de hiérarchie ne compte. Profit, business, capitaux. Rien d’autre.", Author = "Roberto Saviano" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Th%C3%A9r%C3%A8se_Mbailemdana", Text = "Je suis fière de voir les commerçants servir leurs clients dans des enveloppes et sacs biodégradables. Cela prouve qu’ils sont conscients de l’importance que représente désormais la protection de l’environnement.", Author = "Marie-Thérèse Mbailemdana" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fredric_Brown", Text = "Le dernier homme sur la Terre était assis tout seul dans une pièce. Il y eut un coup à la porte…", Author = "Fredric Brown" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Liliane_Banga_Lwaboshi", Text = "Une femme instruite et éduquée est le pilier du foyer et du coup, de la société.", Author = "Liliane Banga Lwaboshi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dieu", Text = "Car Dieu a tant aimé le monde qu’il a donné son Fils unique, afin que quiconque croit en lui ne périsse point, mais qu’il ait la vie éternelle.", Author = "Dieu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Margaret_Mead", Text = "Ne doutez jamais qu'un petit groupe de citoyens engagés et réfléchis puisse changer le monde. En réalité, cela se passe toujours de cette manière.", Author = "Margaret Mead" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Isabelle_de_Montolieu", Text = "Ma patrie est celle de Jean-Jacques Rousseau. Je fus longtemps enthousiaste de son génie et de ses ouvrages", Author = "Isabelle de Montolieu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nathalie_Badate", Text = "On est des combattantes, il fallait retrouver la motivation de continuer la lutte sinon on aura un goût d’inachevé. Donc, ça m’a redonné des forces.", Author = "Nathalie Badate" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Caroline_Faye_Diop", Text = "La présence d’une seule voix féminine au sein d’une assemblée de voix masculines ne peut constituer un réel poids. Mais celle de Caroline a compté lors du vote du Code de la famille, portant la voix de toutes les autres femmes aphones jusque-là.", Author = "Caroline Faye Diop" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Corine_Pelluchon", Text = "Peu de personnes ont compris que le défi soulevé par une économie décarbonée, était de transformer certains renoncements en perspectives de bonheur.", Author = "Corine Pelluchon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/O%27Neige_N%27Sele", Text = "Si vos rêves ne vous font pas peur alors ils ne sont pas assez grands", Author = "O'Neige N'Sele" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Chinelo_Okparanta", Text = "sous les branches de l'udala. Nous devons apprendre à jeûner pour chasser la colère .", Author = "Chinelo Okparanta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Massa_Makan_Diabat%C3%A9", Text = "Pour grands que soient les rois, ils sont ce que nous sommes.", Author = "Massa Makan Diabaté" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fant%C3%B4mas", Text = "Fantômas: L’humanité. Quel merveilleux spectacle de marionnettes! Comment pourrais-je m'ennuyer?", Author = "Fantômas" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/H%C3%A9l%C3%A8ne_Dorion", Text = "Mes forêts sont de longues traînées de temps\nElles sont des aiguilles qui percent la terre\ndéchirent le ciel\navec les étoiles qui tombent", Author = "Hélène Dorion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Seigneur_des_anneaux", Text = "Un Anneau pour les gouverner tous, un Anneau pour les trouver\nUn Anneau pour les amener tous et dans les ténèbres les lier", Author = "Le Seigneur des anneaux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Perp%C3%A9tue_Nshimirimana", Text = "Marguerite était morte. C'était très dur à accepter.  Du fond de ma douleur, une petite lueur de consolation s'était allumée. Je l'avais enterrée, c'était très important.", Author = "Perpétue Nshimirimana" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Theresa_May", Text = "Je veux que la Grande-Bretagne soit la grande méritocratie du monde – un pays où chacun a une chance équitable d’aller aussi loin que son talent et son travail acharné le permettent.", Author = "Theresa May" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pepita_D", Text = "Soyons tous forts contre le Covid-19. Sortons masqués et respectons les consignes.", Author = "Pepita D" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-Joseph_Proudhon", Text = "La propriété, c'est le vol!", Author = "Pierre-Joseph Proudhon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "[Karl Marx est] un esprit d'une nature dissolvante, d'un caractère dominateur, sans fortes croyances philosophiques ou religieuses, et inspiré par des haines plutôt que par l'amour.", Author = "Giuseppe Mazzini" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89ric_Plamondon", Text = "Le meilleur moyen d'être le premier, c'est d'être le premier dans une certaine catégorie. Le meilleur moyen d'être premier dans une certaine catégorie, c'est d'inventer la catégorie.", Author = "Éric Plamondon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Whoopi_Goldberg", Text = "Si quelqu'un vous dit tu me complète, courrez!", Author = "Whoopi Goldberg" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Stefan_Wul", Text = "Si cet homme meurt, je ne regretterai pas de l'avoir perdu, je regretterai d'avoir espéré un instant qu'il existait un individu de plus joignant les trois qualités: intelligence, force et réceptivité à la chance.", Author = "Stefan Wul" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/W._E._B._Du_Bois", Text = "Le problème du XXe siècle est le problème de la ligne de partage des couleurs.", Author = "W. E. B. Du Bois" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tim_Cook", Text = "Vous pouvez combiner un grille-pain et un réfrigérateur, mais ces éléments ne plairont probablement pas à l’utilisateur.", Author = "Tim Cook" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_Under", Text = "Comment pourrais-je dormir, alors que j’aime tant!\nLa lune sur le plancher a mis des feuilles d’argent,\nau ciel comme des larmes éclosent des étoiles.\nComment pourrais-je, et toi et moi, nous oublier!", Author = "Marie Under" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Akpene_Diata_Hoggar", Text = "J’espère gagner la couronne et rendre le Ghana fier.", Author = "Akpene Diata Hoggar" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne_Comn%C3%A8ne", Text = "C'était l'Occident tout entier, tout ce qu'il y a de nations barbares habitant le pays situé de l'autre rive de l'Adriatique et des colonnes d'Hercule qui marchait sur l'Asie.", Author = "Anne Comnène" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/%C3%89mulation", Text = "Je pris le parti de l’accompagner, autant par attachement pour mon art que pour sa personne; je ne pouvais plus me passer de lui; je profitais moi-même à lui donner des leçons, et les questions qu’il me faisait seront des leçons pour ma vie: j'ai perdu mon émulation.", Author = "Émulation" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Foudre", Text = "Nous prîmes congé de lui le matin, d'un simple regard qui signifiait à la fois que nous n'appartenions plus à la vie et que, si nous revenions jamais de notre nouvel état, ce serait à la façon des sourciers pour toucher le ciel de notre baguette de foudre.", Author = "Foudre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Amina_Damerdji", Text = "Aïcha courut à travers le village. Ses jambes tremblaient et son coeur battait si fort qu'il semblait vouloir sortir de sa poitrine. Elle connaissait le mot, dhabahine, les égorgeurs. Dhabahine, dhabahine!", Author = "Amina Damerdji" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mexme_Galet", Text = "Galet a sa raison, et qui croira son dire, \nLe hasard, pour le moins, lui promet un empire.", Author = "Mexme Galet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coffi_Codjia", Text = "Si j’avais connu ce qui est en train d’être fait en ce moment, je crois que j’aurais pu arbitrer une finale de Coupe du Monde. Nous allons vers le professionnalisme… Les arbitres de football auront un salaire…S’il plaît à Dieu, la VAR viendra dans notre football.", Author = "Coffi Codjia" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Choses_de_la_vie", Text = "Hélène: Ce soir nous sommes septembre, et j'ai fermé ma chambre, le soleil n'y entrera plus, tu ne m'aimes plus.\nPierre: Je t'aimais tant Hélène, il faut se quitter, les avions partiront sans nous, je ne sais plus t'aimer.", Author = "Les Choses de la vie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diable", Text = "La plus belle des ruses du Diable est de vous persuader qu'il n'existe pas!", Author = "Diable" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Adjoa_Bayor", Text = "Normalement, lorsque vous participez à des tournois, il est toujours important de commencer sur une note gagnante.", Author = "Adjoa Bayor" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Censure", Text = "[L]e censeur crie ce qu’il proscrit.", Author = "Censure" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Angela_Bassett", Text = "L’univers ne vous fait jamais mentir", Author = "Angela Bassett" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Roschdy_Zem", Text = "Acteur ça reste un truc de loser.", Author = "Roschdy Zem" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nutrition", Text = "On croit que la nutrition est une cause majeure dans au moins 35% des cas de cancers. Certains auteurs avancent même le chiffre de 60%. La consommation régulière et abondante de fruits et légumes apporte une protection anticancéreuse indéniable.", Author = "Nutrition" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bernard_Kouchner", Text = "Mais les Bretons, tout le monde s'en fout!", Author = "Bernard Kouchner" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ombilic", Text = "Divinité olmèque\nLes quatre points cardinaux\nmènent à ton ombilic.\nEt dans ton ventre frappe le jour, tout armé.", Author = "Ombilic" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Catherine_Bernard", Text = "Laodamie (à la princesse): Votre cœur jusqu'ici n'a que l'expérience\nD'un amour mutuel heureux dès sa naissance,\nQue rien n'a traversé, qui ne peut à vos voeux\nOffrir qu'un avenir encore plus heureux.\nD'un bonheur si charmant remplie et possédée,\nComment de mes malheurs prendriez-vous l'idée?", Author = "Catherine Bernard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sophie_Carquain", Text = "Un auteur, tout comme un comédien, est victime d'un défaut d'être.", Author = "Sophie Carquain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeanne_d%27Arc", Text = "(Interrogée si elle sait bien qu’elle soit en la grâce de Dieu, répond):\nSi je n'y suis, Dieu m'y veuille mettre, et si j'y suis, Dieu m'y veuille tenir.", Author = "Jeanne d'Arc" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Dobermann", Text = "Inspecteur Sauveur Cristini: Ils ont tous des têtes de camés, ça s'défonce, ça s'flingue ... c'est la mode, avec moi tout ces bouffons y s'raient déjà morts.", Author = "Dobermann" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Hollande", Text = "Faire simple, ce n'est pas faire médiocre, ou même banal, c'est au contraire avoir le respect des français... être exemplaire", Author = "François Hollande" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Afua_Hirsch", Text = "Les réseaux sociaux sont saturés de souvenirs poignants d’un héritage que l’establishment britannique refuse de reconnaître. Le pillage des terres et des diamants en Afrique du Sud, crimes qui ornaient la couronne même de la reine.", Author = "Afua Hirsch" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Immoraliste", Text = "Je ne suis ni triste, ni gai; l'air d'ici vous emplit d'une exhaltation très vague et vous fait connaître un état qui paraît aussi loin de la gaieté que de la peine; peut-être que c'est le bonheur.", Author = "L'Immoraliste" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andrea_Camilleri", Text = "Une bordille de dégueulasserie de nuit toute gangassée, et que tu vires et que tu tournes, que tu t'endors et tu t'aréveilles, que tu te lèves et tu te couches. Et pas à cause d'une bâffrée de poulpes au sel ou de sardines à la becfigue qu'il se serait faite le soir d'avant […]", Author = "Andrea Camilleri" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9pression_%28psychiatrie%29", Text = "Quand on n’a pas vécu ça de près – les crises d’angoisse, les attaques de panique, quand on croit qu’on va mourir… – ou la vraie dépression, on a tendance à croire que c’est un caprice de gens qui ont besoin d’un coup de pied au cul. Et il n’y a rien de pire pour vous enfoncer.", Author = "Dépression (psychiatrie)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Georgina_Dufoix", Text = "Nos concitoyens n'ont pas compris que derrière le mariage des homosexuels, c'est la théorie du genre qui est insufflée dans la société française. Cette théorie qui vient des États-Unis estime qu'homme et femme sont interchangeables.", Author = "Georgina Dufoix" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jo_G%C3%BCstin", Text = "Si tu dois te moquer de quelqu’un, c’est de toi.", Author = "Jo Güstin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_hommes_pr%C3%A9f%C3%A8rent_les_blondes", Text = "Lorelei: Est-ce que tu le trouves trop petit, Dorothy?\nDorothy: Il ne lui manque que la carafe pour mettre en dessous!", Author = "Les hommes préfèrent les blondes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jeanne_Mbella_Ngom", Text = "Il faut débâillonner la femme afin qu´elle comprenne qu´elle doit être au front et arracher sa liberté et ses droits.", Author = "Jeanne Mbella Ngom" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mario_Puzo", Text = "Un avocat habile vole bien plus d’argent avec son porte-documents qu’un millier de brigands avec leurs pistolets et leurs cagoules.", Author = "Mario Puzo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tyrannosaure", Text = "Un Tyrannosaurus rex. Le Lézard du Tonnerre, le plus terrible monstre de l'histoire. Signez ce papier. Quoi qu'il arrive, nous ne sommes pas responsables. Ces dinosaures sont affamés.", Author = "Tyrannosaure" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fight_Club", Text = "Pendant un long moment pourtant, Tyler et moi avons été les meilleurs amis du monde. Les gens n'arrêtent pas de me demander: est ce que j'étais au courant pour Tyler Durden?", Author = "Fight Club" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Koko_Ateba", Text = "Au fait quelqu’un peut il me dire pourquoi je ne suis jamais invitée dans ce genre de truc? La soirée du tourisme et du potentiel de notre pays… je ne suis pas assez typique d’une région?", Author = "Koko Ateba" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rosamund_Haden", Text = "Désormais,  le mouvement pour la liberté était comme un fleuve en crue: rien ne pouvait l'arrêter. Il n' y avait d'autre choix que monter dans une barque et suivre le courant, ou bien se noyer.", Author = "Rosamund Haden" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sport", Text = "Le sport, en quelques décennies, est devenu le plus grand phénomène de masse mondial du XXe siècle, sans doute la nouvelle et vraie religion du XXIe.", Author = "Sport" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ren%C3%A9_Daumal", Text = "Ce qui jaillira de ce beau massacre pourrait bien être plus réel et tangible qu'on le croit, une statue du vide qui se met en marche, bloc de lumière pleine. Une lumière inconnue trouera les fronts, ouvrant un nouvel œil mortel, une lumière unique, celle qui signifie: non!", Author = "René Daumal" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Lina_Ben_Mhenni", Text = "Le départ d’un dictateur n’est pas la fin de la révolution, c’est son début.", Author = "Lina Ben Mhenni" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Domenico_Margiotta", Text = "Vous pouvez faire brûler mon nom entre les colonnes. Vous pouvez me vouer à toutes les malédictions infernales. Trop heureux je suis d'avoir brisé les chaînes que votre Grand Architecte impose; trop de joie j'ai à vous déclarer que je suis plus que démissionnaire […]", Author = "Domenico Margiotta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gravit%C3%A9", Text = "Tomber amoureux n'est pas du tout la chose la plus stupide que font les gens - mais la force de gravité ne peut en être tenue pour responsable.", Author = "Gravité" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/R%C3%A9v%C3%A9rien_Rurangwa", Text = "Ils m’ont tué, moi et toute ma famille, sur une colline du Rwanda, en avril 1994, mais je ne suis pas mort.", Author = "Révérien Rurangwa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ajara_Nchout", Text = "Certains musulmans ne veulent pas que les femmes jouent au football, mais elles peuvent devenir une légende demain. Dans la vie, on ne sait pas ce qui peut arriver demain.", Author = "Ajara Nchout" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diablo", Text = "Ahhh! De la viande fraiche!", Author = "Diablo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philostrate_de_Lemnos", Text = "Que dire de ces belles cavernes, de ces sources que fréquentent les femelles des centaures, semblables à des Naiades si nous oublions leur nature chevaline, rappelant à certains égards les Amazones: c'est le cheval uni à la femme, c'est la force s'ajoutant à la délicatesse des formes.", Author = "Philostrate de Lemnos" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Oscar_Niemeyer", Text = "L’œuvre architecturale doit être belle, légère, différente. J’ai toujours été rebelle aux règles préétablies, aux contraintes didactiques, à l’angle droit, qui est une création rigide de l’homme.", Author = "Oscar Niemeyer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Albert_Pike", Text = "Le Pape des Francs-maçons se place en face du Pape des catholiques, Albert Pike en face de Léon XIII, le représentant de Satan sur la terre en face du représentant de Dieu sur terre.", Author = "Albert Pike" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C3%A9cile_Manorohanta", Text = "On vit dans un monde qui évolue sans cesse et où il y a une forte prédominance des hommes, donc il faut être vigilant et flexible dans les prises de décisions pour pouvoir avancer.", Author = "Cécile Manorohanta" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Prades_%28Pyr%C3%A9n%C3%A9es-Orientales%29", Text = "Prades est le premier bourg un peu considérable que l'on rencontre après Perpignan, et c'est aussi le dernier. Les voitures ne peuvent aller au-delà, et on ne peut voyager que sur des chevaux.", Author = "Prades (Pyrénées-Orientales)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Part_de_l%27autre", Text = "Le bonheur se fortifie du malheur des autres.", Author = "La Part de l'autre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marina_L%C3%A9vy", Text = "Les océans nous protègent en fait des pires effets du réchauffement climatique.", Author = "Marina Lévy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vin_et_religion", Text = "Tour à tour offrande divine ou égérie des poètes, le vin exprime, sous toutes les civilisations, la gaîté, la franchise, le courage ou la force.", Author = "Vin et religion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Maria_Helena_Semedo", Text = "L’avenir est entre nos mains. Nous devons réformer et renforcer la gouvernance de l’eau et des terres .", Author = "Maria Helena Semedo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christiane_Cellier", Text = "Chacun de nous naît avec un certain capital nerveux. J’ai eu déjà tant de coups durs que ce capital, je le sens parfois bien entamé et moi-même bien vulnérable. Je ne veux pas m’user par trop, émotionnellement, au cinéma. Après tout, je ne sais pas ce qui m’attend encore dans la vraie vie", Author = "Christiane Cellier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fatim-Zahra_Ammor", Text = "Le tourisme contribue de manière significative à l'économie marocaine et joue un rôle clé dans le développement du pays.", Author = "Fatim-Zahra Ammor" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Nelly_Roussel", Text = "Ô femmes! L'heure a sonné des révoltes libératrices. Ce n'est pas la charité que nous demandons c'est la justice.", Author = "Nelly Roussel" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Euro", Text = "Selon une étude de S&P Global Market Intelligence, le bilan total des six plus grandes banques françaises frôlait les 10.000 milliards d’euros d’actifs à fin 2022, soit près de quatre fois le PIB hexagonal.", Author = "Euro" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Boudor", Text = "Que celui qui sait chanter lève le doigt", Author = "Boudor" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mj_Rodriguez", Text = "Nous devons créer un plan d'égalité pour les femmes transgenres afin que nous ne devenions pas une tendance. Je ne veux pas être une tendance.", Author = "Mj Rodriguez" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Gautier", Text = "On avait revu sur les autoroutes des citoyens honorables prêts à tout pour fuir. Les plus anciens avaient des réminiscences de juin 1940, les moins vieux d'Alger en juillet 1962. C'était toujours le même peuple qui fuyait.", Author = "Philippe Gautier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Hypatie", Text = "Le vil Galiléen t'a frappée et maudite,\nMais tu tombas plus grande! Et maintenant, hélas!\nLe souffle de Platon et le corps d'Aphrodite\nSont partis à jamais pour les beaux cieux d'Hellas!", Author = "Hypatie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Manent", Text = "Le christianisme a introduit un écart inédit entre ce que font les hommes et ce qu’ils disent. [...] La parole chrétienne demande aux hommes d’aimer ce qu’ils haïssent naturellement — leurs ennemis — et de haïr ce qu’ils aiment naturellement — eux-mêmes.", Author = "Pierre Manent" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mouvance_identitaire", Text = "Les identitaires instrumentalisent [...] la cause palestinienne afin de développer leurs thèses antisémites.", Author = "Mouvance identitaire" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Louis_Antoine_de_Saint-Just", Text = "Les révolutions sont moins un accident des armes qu'un accident des lois.", Author = "Louis Antoine de Saint-Just" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/21_Grammes", Text = "Paul (en voix off): On dit que nous perdons tous 21 grammes au moment précis de notre mort. Le poids de cinq pièces de monnaie, le poids d'une barre de chocolat, le poids d'un colibri. 21 grammes. Est-ce le poids de notre âme? Est-ce le poids de la vie?", Author = "21 Grammes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Billie_Eilish", Text = "Internet s'emballait devant le procès de stars de cinéma alors que Roe vs Wade était en train d'être abrogé.", Author = "Billie Eilish" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ath%C3%A9na", Text = "Je suis venue du ciel pour calmer ta fureur: me veux-tu obéir?", Author = "Athéna" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Automatisme_%28psychologie%29", Text = "L'automatisme, c'est activité humaine dans ses formes les plus simples, les plus rudimentaires", Author = "Automatisme (psychologie)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Farouk_Hosni", Text = "Je ne conçois pas d’être un ministre — et surtout pas ministre de la culture — sans imagination, sans pouvoir mobiliser l’imagination, la mienne, ainsi que celle des autres, au service d’une politique culturelle audacieuse.", Author = "Farouk Hosni" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/John_Muir", Text = "Chacun d'entre nous a besoin de beauté comme de pain, de places pour jouer et de lieux de prière, d'endroits où la nature puisse le guérir et se réjouir, et le fortifier dans son corps et son âme.", Author = "John Muir" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/L%27Ennemi_public_n%C2%BA_1_%28film%2C_1953%29", Text = "Ce qui manque aux honnêtes gens, c'est les revolvers.", Author = "L'Ennemi public nº 1 (film, 1953)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pauline_Opango", Text = "Une maman qui a perdu son mari et qui est restée fidèle. Elle est restée avec ses enfants sans déviation, au service de sa famille et de toute la communauté nationale. Elle est une maman sage qui a suivi les traces de son mari.", Author = "Pauline Opango" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne_Cheng", Text = "L'ignorance ou les idées préconçues de nos concitoyens, y compris de nos élites, concernant la Chine et sa culture se maintiennent à un niveau préoccupant.", Author = "Anne Cheng" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Neil_Gaiman", Text = "Dis-lui bien qu'on a reprogrammé cette réalité de merde. Que le langage est un virus, que la religion est un système d'exploitation et que les prières ne sont rien d'autre que du spam à la con!", Author = "Neil Gaiman" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_p%C3%A8re_No%C3%ABl_est_une_ordure", Text = "Je lui fais pas mal, je lui passe un peu d'eau sur son visage, elle me fait une crise de nerfs, elle fait tout le temps ça, vous la connaissez pas.", Author = "Le père Noël est une ordure" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ch%C3%AAne", Text = "La tempête forme des cuisses puissantes dans le vallonnement de la vague et dans la nuque du chêne. On croirait à un combat entre la branche et l'écume. Ce n'est pourtant que jeu. La divinité y assiste et préserve les limites.", Author = "Chêne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vincent_Gerbe", Text = "Celui qui adopte un autre mode de vie, d'une façon visible et concrète, sape les bases du conformisme. Il se heurtre à l'intolérance, car on est immédiatement suspect si l'on est différent, même dans son assiette.", Author = "Vincent Gerbe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Anne_Sylvestre", Text = "Mon mari est parti un beau matin d'automne\nParti je ne sais où\nJe me rappelle bien la vendange était bonne\nEt le vin était doux", Author = "Anne Sylvestre" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Diff%C3%A9rentes_Saisons", Text = "L'expertise financière que demande un individu ou une entreprise est en rapport direct avec le nombre de gens que cet individu ou cette entreprise est en train de baiser.", Author = "Différentes Saisons" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/The_Beatles", Text = "Pourquoi a-t-elle dû partir, je ne le sais pas, elle ne l'a pas dit\nJ'ai dit quelque chose qu'il ne fallait pas, et maintenant je voudrais être hier", Author = "The Beatles" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaamelott/Le_tavernier", Text = "Sire, si vous me les enlevez, c’est un tiers de mes revenus qui fout le camp. Parce qu’ils font pas que boire! Ils mangent là un jour sur deux ...", Author = "Kaamelott/Le tavernier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-George_Buffet", Text = "Être au pouvoir, fût-on communiste, n'abolit pas en soi les rapports de classe, les rapports de force. Croire que l'on pourrait agir sans le peuple, être porteur de ses aspirations à sa place, le libérer par en haut, c'est là une grave erreur.", Author = "Marie-George Buffet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Koumanthio_Diallo", Text = "Les trois piliers fondamentaux de cette culture qui sont: la femme, la vache et la foi, et démontrent combien la culture peul du Fouta-Djalon a réservé une bonne place à la femme.", Author = "Koumanthio Diallo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/D%C3%A9go%C3%BBt", Text = "J'aime la franchise, les hypocrites me dégoûtent, il faut préférer la jouissance physique à tout et ne s'abandonner qu'avec soi-même; l'effusion partagée ressemble à deux autos face à face, qui cherchent mutuellement à se faire reculer.", Author = "Dégoût" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ra%C3%AFssa_Gb%C3%A9dji", Text = "Le contrat c’est le micro. C’est toujours le micro. J’ai commencé par chanter au micro, ensuite je suis passée à la radio et maintenant je reviens un peu plus au chant", Author = "Raïssa Gbédji" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Les_Ailes_de_l%27enfer", Text = "Cyrus Grissom: Si jamais tu dis un mot de travers, le prochain ballet aérien auquel tu participeras sera celui des mouches qui viendront voler et butiner sur ton cadavre pourrissant.", Author = "Les Ailes de l'enfer" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Matoub_Loun%C3%A8s", Text = "Je suis de la race des guerriers. Ils peuvent me tuer mais ils ne me feront jamais taire. Je préfère mourir pour mes idées que de lassitude ou de vieillesse.", Author = "Matoub Lounès" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Orgueil_et_Pr%C3%A9jug%C3%A9s_%28film%2C_1940%29", Text = "Mary Bennet: Lui avez-vous dit que vous aviez cinq filles, Papa?\nMr. Bennet: Eh bien, je lui ai dit que s'il rencontrait cinq des filles les plus idiotes d'Angleterre, ça devrait être mes filles!", Author = "Orgueil et Préjugés (film, 1940)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gabriel_Matzneff", Text = "S'appuyer sur un philosophe décrié, citer un poète tombé dans l'oubli, faire l'éloge d'un théologien dont personne ne sait le nom, c'est publier qu'on se sent en communion avec eux, transmettre la flamme, opérer une résurrection.", Author = "Gabriel Matzneff" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Didier_van_Cauwelaert", Text = "À trente ans on inhume encore une promesse; à cinquante on enterre des concessions.", Author = "Didier van Cauwelaert" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Christian_Mistral", Text = "Qui blâmerait un chien de mordre dans le danger, le guépard affamé de dévorer une gazelle pour passer la nuit?", Author = "Christian Mistral" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Andr%C3%A9_Voisin", Text = "De l'équilibre du sol, dépend l'équilibre de la plante, de l'animal et de l'homme.", Author = "André Voisin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cl%C3%A9mentine_Autain", Text = "L’apparition de la pensée queer, par exemple, montre que les oppositions d’hier, entre essentialistes et universalistes (pour faire court), peuvent peut-être se transcender, par une nouvelle approche des identités sexuées.", Author = "Clémentine Autain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean-Pierre_Raffarin", Text = "La route est droite, mais la pente est forte.", Author = "Jean-Pierre Raffarin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Henning_Mankell", Text = "Vieillir, c'est être en proie à l'inquiétude. L'inquiétude envers tout ce qui vous faisait peur quand on était enfant revient quand on est vieux...", Author = "Henning Mankell" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Angela_Aquereburu", Text = "Le spectateur veut voir des choses qui lui ressemblent, des histoires authentiques.", Author = "Angela Aquereburu" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ernest_et_C%C3%A9lestine_%28film%29", Text = "Ernest: Pas de souris dans une maison, jamais! Tu en acceptes une, il en vient mille. Vous êtes comme ça, vous autres, tous les ours te le diront.", Author = "Ernest et Célestine (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Vincent_Lagaf%27", Text = "Jeanne Mas, ils lui ont opéré du sourire, ils ont oublié d'enlever les fils.", Author = "Vincent Lagaf'" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Romy_et_Michelle%2C_10_ans_apr%C3%A8s", Text = "Cowboy: Tu avais raison j'étais un paysan arriéré, un trou du cul… quoique j'ai jamais baisé un mouton, ni ma sœur d'ailleurs.\nHeather Mooney: Pourquoi, ils couraient trop vite pour toi?", Author = "Romy et Michelle, 10 ans après" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ron_Howard", Text = "Nous avons voulu en parler de façon réaliste et sérieuse. Et nous nous sommes dit que plus nous serions honnêtes, plus les rires seraient élevés. C'est une façon de faire remonter la pression.", Author = "Ron Howard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Imre_Kert%C3%A9sz", Text = "Et je suis resté dépouillé, les mains vides. Je me suis retrouvé face à mon cauchemar immatériel et informe: le temps. Il tendait vers moi sa bouche bêtement béante, et je n'avais rien à lui fourrer dans le gosier.", Author = "Imre Kertész" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Th%C3%A9r%C3%A8se_de_Lisieux", Text = "Mon Dieu, je choisis tout. Je ne veux pas être une sainte à moitié, cela ne me fait pas peur de souffrir pour vous, je ne crains qu'une chose c'est de garder ma volonté, prenez-la, car Je choisis tout ce que vous voulez!", Author = "Thérèse de Lisieux" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/M%C3%A9d%C3%A9e_%28mythologie%29", Text = "Et je n'approuve pas le citoyen à l'humeur insolente\nqui blesse les siens en dédaignant de les comprendre.", Author = "Médée (mythologie)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Protocoles_des_Sages_de_Sion", Text = "Aux premières époques de la vie sociale, ils étaient soumis à la force brutale et aveugle, puis ils se soumirent à la loi, qui n’est, en réalité, que la même force masquée. Cette constatation me mène à déduire que, de par la loi naturelle, le droit réside dans la force.", Author = "Protocoles des Sages de Sion" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Princesse_Mononok%C3%A9", Text = "Ashitaka: On dit que femmes heureuses font bon village.", Author = "Princesse Mononoké" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/J%C3%A9r%C3%B4me_Garcin", Text = "Mon père est mort d’une chute de cheval le samedi 21 avril 1973, veille de Pâques, dans l’insoucieuse et très civilisée forêt de Rambouillet. Il avait quarante-cinq ans, j’allais en avoir dix-sept. Nous ne vieillirons pas ensemble.", Author = "Jérôme Garcin" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniella_Okeke", Text = "Mon conseil aux femmes nigérianes est de ne pas sacrifier leur dignité pour réussir dans la vie.", Author = "Daniella Okeke" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aholou_K%C3%A8k%C3%A8", Text = "L’avenir d’un être humain est entre les mains du créateur.", Author = "Aholou Kèkè" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie-Ange_Mushobekwa", Text = "Chaque démocratie a besoin des institutions fortes et stables mais aussi d'une opposition constructive.", Author = "Marie-Ange Mushobekwa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cyprien_%28film%29", Text = "Shabbat shalom les pédés! C'est kascher chez vous?", Author = "Cyprien (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marie_d%27Anjou", Text = "C’est mon seigneur, il a tout pouvoir sur mes actions, et moi, aucun sur les siennes.", Author = "Marie d'Anjou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Ney", Text = "J'aime mieux être grenadier que général dans de telles conditions. Je suis prêt à verser tout mon sang, mais je désire que ce soit utilement.", Author = "Michel Ney" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Katharine_Hepburn", Text = "Je n'ai aucune crainte de la mort. Ce doit être merveilleux, comme un long sommeil. Et puis, regardons les choses en face: ce qui compte c'est ce qu'on fait de sa vie.", Author = "Katharine Hepburn" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Excalibur_%28film%29", Text = "Merlin: Voyez l'épée de la puissance, Excalibur. Elle fut forgée lorsque le monde était jeune, lorsque l'oiseau, la bête et la fleur ne faisaient qu'un avec l'homme, et que la mort n'était qu'un rêve.", Author = "Excalibur (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tiburce_Koffi", Text = "Pleurer d’amour est un petit rien qui tisse le lien entre deux êtres anonymes.", Author = "Tiburce Koffi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/28_Jours_plus_tard", Text = "Mark: Donc, première leçon, ne jamais se déplacer seul sauf s'il n'y a aucune autre solution. Seconde leçon, ne sortir que pendant la journée sauf s'il n'y a aucune autre solution. Demain, on t'accompagnera, on ira voir tes parents morts tous ensemble, d'accord?", Author = "28 Jours plus tard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/David_Revoy", Text = "Même si mon produit principal c'est le webcomic, je sais qu'il y a toute une génération pour qui un vrai auteur, c'est quelqu'un qui fait des livres.", Author = "David Revoy" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Envie", Text = "En général, la plupart des hommes ne se portent à commettre l'injustice que pour obtenir les choses qu'ils convoitent. Dès lors, la cupidité est la plus grande source de l'injustice.", Author = "Envie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mounia_Youssef", Text = "L’art a un grand impact sur les individus dans la société dans laquelle nous vivons. Les choses changent grâce à l’art, les mentalités changent.", Author = "Mounia Youssef" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Souverainet%C3%A9", Text = "La théorie de la souveraineté est liée à une forme de pouvoir qui s'exerce sur la terre et les produits de la terre, beaucoup plus que sur les corps et sur ce qu'ils font.", Author = "Souveraineté" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/FBI_%3A_port%C3%A9s_disparus", Text = "Samantha: T'as décidé d'en parler à tout le monde, c'est ça?\nMartin: Eh Samantha, tu sais déjà ce que j'en pense alors, mais c'est pas le moment d'en parler!\n\nSamantha: Ok alors on va pas en parler.", Author = "FBI : portés disparus" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tekiath_Ben_Yessouf", Text = "Je ne peux pas vous parler de mon future avec le taekwondo parce que je ne sais pas encore combien de temps va durer ma carrière. Pour l’instant je vise les jeux olympiques de Tokyo 2021.", Author = "Tekiath Ben Yessouf" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Wandiswa_Ntengento", Text = "Les réseaux sociaux ont rendu l'information plus accessible au public et ont mis les organes de presse sous pression pour diffuser les nouvelles plus rapidement qu'auparavant.", Author = "Wandiswa Ntengento" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Omar_Khayyam", Text = "J'ai lancé contre une pierre un bol cette nuit;\nL'acte brutal, j'étais ivre quand je l'ai commis;\nLe bol m'a dit en son langage de bol:\nJ'ai été ce que tu es! tu seras toi aussi ce que je suis!", Author = "Omar Khayyam" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Syllabus_du_pape_Pie_IX", Text = "On sait aussi comment, instruit par sa propre expérience et éclairé de la lumière divine, Pie IX pulvérisa le libéralisme, c’est-à-dire le Maçonnisme avec le marteau du Syllabus.", Author = "Syllabus du pape Pie IX" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rumeur", Text = "Il marche dans la plaine immense, \nVa, vient, lance la graine au loin, \nRouvre sa main, et recommence, \nEt je médite, obscur témoin,\n\nPendant que, déployant ses voiles, \nL'ombre, où se mêle une rumeur, \nSemble élargir jusqu'aux étoiles \nLe geste auguste du semeur.", Author = "Rumeur" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Cath%C3%A9rine_Marie_T%C3%A9wend%C3%A9_Manly_Loagboko", Text = "Chaque enfant est le reflet de l’éducation et de l’instruction reçues mais aussi de l’ambiance familiale dans lequel il vit.", Author = "Cathérine Marie Téwendé Manly Loagboko" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Mamoru_Hosoda", Text = "Je suis exactement l'opposé de Miyazaki! Pendant trois ans de production, je ne me suis jamais mis en colère et je n'ai eu besoin de hurler sur personne.", Author = "Mamoru Hosoda" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre-Yves_Bourdil", Text = "Assumer le caractère paradoxal de l'existence est un acte, et c'est cet acte qui nous constitue en êtres humains.", Author = "Pierre-Yves Bourdil" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Rebo_Tchulo", Text = "Je n’ai pas l’habitude de publier des informations erronées dans le simple but de créer le buzz. La plupart de mes publications sont vraies et je ne force pas les buzz.", Author = "Rebo Tchulo" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Eliane_Ekra", Text = "La femme est naturellement sans nomination officielle et sans salaire, plusieurs fois Ministre dans son foyer.", Author = "Eliane Ekra" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Robert_McLiam_Wilson", Text = "Ne vous y trompez pas, mes si cartésiens Français chéris, vous êtes engagés dans une guerre à la con contre des connards sans cervelle. Du vide figé dans une posture, rempli de semi-arguments malinformés, empruntés à d’autres débats, d’autres conflits.", Author = "Robert McLiam Wilson" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Le_Pont_de_la_rivi%C3%A8re_Kwa%C3%AF_%28film%29", Text = "Colonel Nicholson: Nous pouvons donner à ces sauvages une leçon sur l'efficacité des méthodes occidentales qui leur fera honte.", Author = "Le Pont de la rivière Kwaï (film)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sobdibe_Kemaye", Text = "Étant donné que la littérature orale n’est pas écrite, il est difficile de la documenter et de la préserver. Les récits peuvent être modifiés ou perdus au fil du temps, ce qui entraîne une perte irremplaçable du patrimoine culturel.", Author = "Sobdibe Kemaye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Michel_Henry", Text = "Ce qui se sent sans que ce soit par l'intermédiaire d'un sens est dans son essence affectivité.", Author = "Michel Henry" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Barbe", Text = "C’était cela l’amour, pensait-il: s’évanouir comme un souffle dans la chaleur d’une peau plus douce que la sienne, s’oublier et renaître.", Author = "Jean Barbe" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Madison_Grant", Text = "Au point de vue zoologique, depuis le début de l'époque tertiaire, l'Afrique du Nord, au nord du Sahara, fait partie de l'Europe. Cela est vrai à la fois des animaux et des races humaines. Les Berbères de l'Afrique du Nord sont identiques comme race aux Espagnols et aux Italiens du Sud.", Author = "Madison Grant" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Damso", Text = "Regarde au-d'ssus, il n'y a plus de nuages, la pluie ne risque pas de tomber\nRegarde mon cœur, il n'a plus de grillage, mais personne ne risque d'y entrer", Author = "Damso" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pr%C3%A9tention", Text = "La prétention fait écrire.", Author = "Prétention" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/C%C3%A9sar_%28sculpteur%29", Text = "Je n’ai pas d’imagination. Elle ne me vient qu’avec le toucher et les yeux. Sans ces deux éléments, le cerveau ne fonctionne pas.", Author = "César (sculpteur)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ousseina_Alidou", Text = "Je plaide aussi pour la scolarisation des filles ainsi que la valorisation des femmes chercheures et les produits de leurs efforts. Avec la grâce de Dieu tout est possible.", Author = "Ousseina Alidou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tendresse", Text = "La vie creuse devant nous le gouffre de toutes les caresses qui ont manqué. Qu'avons-nous à faire auprès de nous de cet ange qui n'a pas su se montrer?", Author = "Tendresse" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Monica_Bellucci", Text = "Peinture, musique, littérature, cinéma: seul le temps atteste de la valeur d'une œuvre. L'instant est toujours soumis aux aléas, aux émotions, à un certain état d'esprit. Pour pouvoir jauger, il faut attendre. Passer après le public, les critiques, les modes… Juger à nu. Poser un œil vierge.", Author = "Monica Bellucci" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Zeinabou_Mindaoudou_Souley", Text = "La sécurité nucléaire reste liée à la non-prolifération et au désarmement, et je voudrais appeler, au nom du Gouvernement, tous les Etats à respecter leurs engagements.", Author = "Zeinabou Mindaoudou Souley" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Graham_Masterton", Text = "L’ennui, lorsque vous vous cachez, c’est que, à un moment ou à un autre, vous êtes obligé de sortir de votre cachette et d’affronter ce qui vous a amené à vous cacher.", Author = "Graham Masterton" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Felicia_Impastato", Text = "Etudiez, car en étudiant vous ouvrez votre tête et vous comprenez ce qui est bien et ce qui ne l'est pas", Author = "Felicia Impastato" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Daniel_de_Roulet", Text = "Dans ma génération helvétique, ni moi ni tant d'autres n'avons été des militants jusqu'au-boutistes. Dans un pays étouffé par sa propre guerre froide, nous n'avons été que des militants intermittents.", Author = "Daniel de Roulet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Limp_Bizkit", Text = "Lourde est la tête qui porte la couronne", Author = "Limp Bizkit" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Philippe_Boulanger_%28g%C3%A9ographe%29", Text = "La géographie, qui analyse les relations entre les hommes et leur territoire, est un savoir stratégique dès les premières évolutions de la pensée militaire.", Author = "Philippe Boulanger (géographe)" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Aquitains", Text = "Le fleuve Garonne sépare les Gaulois des Aquitains.", Author = "Aquitains" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Disparition", Text = "— Le jour où disparaîtront d'un seul coup tes amis! où d'un seul coup disparaîtra la terre et ce qu'elle porte, hormis toi! quand tu seras seul on te croira mort; c'est on qui le sera. L'univers meurt chaque fois que meurt un homme, et il y a beaucoup d'hommes parmi les hommes.", Author = "Disparition" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Florence_Muleka_Bajikila", Text = "Chaque pas que je fais construit la femme que je deviens", Author = "Florence Muleka Bajikila" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Laurence_des_Cars", Text = "La Joconde est entourée de chefs-d’œuvre que personne ne regarde", Author = "Laurence des Cars" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Yasmine_Char", Text = "Les mots sortent trop vite. Les mots glissent, heurtent, s'entrechoquent et nous restons immobiles, plus petits que la parole, à regarder le cœur en lambeaux notre idéal qui s'écroule.", Author = "Yasmine Char" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Markoosie_Patsauq", Text = "Le vent est si fort qu'on l'entend même à l'intérieur de l'iglou. A l'évidence, partir à la chasse est toujours impossible. La tempête de neige dure depuis trois jours.", Author = "Markoosie Patsauq" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/N%C3%A9lie_Jacquemart", Text = "J’espère que j’aurai Chaalis, c’est mon plus vif désir. [...] un lieu de repos et d’activité, cela est bon et sain car je ne suis qu’une pierre roulante.", Author = "Nélie Jacquemart" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Justine_Lumumba_Kasule", Text = "Vous devez vous assurer que les produits que vous fabriquez répondent à des normes élevées et sont de bonne qualité. Même lorsque vous êtes mannequin ou que vous présentez vos créations de mode, vous devez continuer à faire ce qu'il faut, sourire et avoir confiance en vous.", Author = "Justine Lumumba Kasule" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kitia_Tour%C3%A9", Text = "Le chasseur reconnait toujours la taille du gibier qu’il suit à la grandeur de l’empreinte que l’animal laisse dans la boue.", Author = "Kitia Touré" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fant%C3%B4mas_se_d%C3%A9cha%C3%AEne", Text = "Hélène Gurn, fiancée de Fandor: Pourquoi ce chantage? Pourquoi tout ce mal?\nFantômas: Où est le mal? Où est le bien? Pour moi, le bien, c'est ce que je veux, ce que je désire...", Author = "Fantômas se déchaîne" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Guillaume_Ier_d%27Orange-Nassau", Text = "Nul besoin d’espérer pour entreprendre, nul besoin de réussir pour persévérer.", Author = "Guillaume Ier d'Orange-Nassau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/La_Fille_de_d%27Artagnan", Text = "Duc de Crassac: Un nègre en Périgord, ça vous a l'air de quoi? Les sauvages, on les embarque en Afrique, on les débarque aux Amériques, mais on leur fait pas visiter les Provinces!", Author = "La Fille de d'Artagnan" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Kaamelott/Yvain", Text = "Je refuse d’aller me battre pour soutenir une politique d’expansion territoriale dont je ne reconnais pas la légitimité.", Author = "Kaamelott/Yvain" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Matrix", Text = "Je montrerai à ces gens ce que vous ne voulez pas qu'ils voient. Je leur ferai voir un monde sans vous, un monde sans lois ni contrôle, sans limites ni frontières, un monde où tout est possible. Ce que nous en ferons ne dépendra que de vous.", Author = "Matrix" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Si_Mohand_Ou_Mhand", Text = "Je le jure de Tizi-Ouzou\nJusqu’à l’Akfadou\nNul d’eux ne me commandera\n\nPlutôt rompre que plier\nPlutôt être maudit\nDans un pays où les chefs sont des entremetteurs\n\nL’exil m’est prédestiné\nPar Dieu j’aime mieux l’exil \nQue la loi des pourceaux.", Author = "Si Mohand Ou Mhand" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jacques_Boucher_de_Perthes", Text = "L'Afrique française sort de la barbarie , l'Espagne y retourne; nous rendons aux Maures d'Afrique ce qu'ils nous avaient donné: la civilisation.", Author = "Jacques Boucher de Perthes" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Souleymane_Ciss%C3%A9", Text = "Ma façon de vivre, c’est de croire en l’avenir; si j’étais fataliste, je ne serais pas cinéaste. Rien ne me poussait à faire du cinéma. C’est moi qui l’ai choisi. Je voulais voir les choses et les faire voir. Quand on a cette curiosité, on ne peut pas être fataliste.", Author = "Souleymane Cissé" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/G%C3%A9rard_Haddad", Text = "On le voit dans son usage en Chine: l'IA sert à augmenter le pouvoir de certains hommes sur leurs semblables. Elle ne produit pas des sages mais des tyrans. L'intelligence, la vraie, ça se cultive en fréquentant d'autres intelligences, qui existent ou ont existé, c'est-à-dire par l'étude.", Author = "Gérard Haddad" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Micheline_Coulibaly", Text = "L'homme africain a beaucoup d'affection et de respect pour la femme. Il a le sens de la famille large. Le seul reproche que je lui fais, c'est de ne pas faire de sa femme une compagne, une confidente.", Author = "Micheline Coulibaly" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ifeoma_Okoye", Text = "L'agression met les gens sur la défensive et les empêche d'écouter la voix de la raison.", Author = "Ifeoma Okoye" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Indira_Gandhi", Text = "Je ne suis pas assez modeste pour dire que je serais incapable de gouverner, mais je ne suis pas vaniteuse au point d'affirmer que d'autres ne pourraient pas remplir cette tâche.", Author = "Indira Gandhi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Open_source", Text = "Ceux qui décrivent la communauté open source comme un regroupement de voleurs ne se souciant pas des droits de reproduction ignorent la justification des licences comme la GPL: les programmateurs open source ne souhaitent pas que leur travail soit volé par d'autres.", Author = "Open source" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Keith_Bostic", Text = "Je pense que jamais nous n’aurions pu aller aussi vite sans l’influence de GNU. Ils étaient manifestement engagés à fond, et nous aimions l’idée.", Author = "Keith Bostic" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Soi", Text = "Pour que deux moi fassent un nous, il faut que les deux soient soi.", Author = "Soi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Julie_Ngungwa", Text = "Julie Ngungwa est engagée a travailler pour s’enrichir , elle a oublié le peuple d’abord, elle est dans le moi d’abord. Cette façon de faire n’est pas conforme à notre idéologie. Nous la considérons déjà comme une anti-tshisekedi", Author = "Julie Ngungwa" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Apostasie", Text = "La Franc-Maçonnerie, qui avait inspiré cette apostasie criminelle, a désorganisé la famille, comme elle a désorganisé l’école.", Author = "Apostasie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/G%C3%A9nie", Text = "Contrairement aux figures de la Vestale ou de Cornalie, qui exaltent le foyer et la maternité, celle de Sappho raconte l'histoire de la femme de génie, rejetée par des hommes incultes, jeunes et beaux, qui meurt parce qu'elle a abdiqué les pouvoirs de l'esprit.", Author = "Génie" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Marine_Tondelier", Text = "Il n'y a pas beaucoup de meufs en politique. C'est comme ça, on fait avec.", Author = "Marine Tondelier" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Coumba_Dieng_Sow", Text = "Le Covid-19 ne pouvait arriver à un pire moment pour les communautés vulnérables de l'Afrique de l'Ouest.", Author = "Coumba Dieng Sow" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Jean_Jullien", Text = "Les images qui fonctionnent sont celles devant lesquelles les gens peuvent se dire: c'est bien vu, je fais ça tout le temps.", Author = "Jean Jullien" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pierre_Ouellet", Text = "On n'est pas plus sûr que sa vie soit bien la sienne qu'un père n'est certain que son fils soit de lui: tout tient à un nom, dans lequel il faut croire, même quand on est un homme de peu de foi.", Author = "Pierre Ouellet" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Tabac", Text = "Paris est plus grand que Picabia mais Picabia est la capitale de Paris; Breton est un grand fleuve de tabac turc et la mer se jette dans ce fleuve pour monter vers l'Infini.", Author = "Tabac" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Thomas_Watson%2C_Junior", Text = "Je crois que si une organisation se confronte aux défis d'un monde changeant, elle doit être préparée à changer tout sur elle-même, à l'exception de ses croyances.", Author = "Thomas Watson, Junior" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Banquise", Text = "Rrose Sélavy fonde une banque antarctique sur la banquise antiartistique.", Author = "Banquise" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Henry_David_Thoreau", Text = "Mais, pour parler pragmatiquement et en tant que citoyen, je réclame, contrairement à ceux qui se prétendent anti-gouvernement, non pas la disparition immédiate de tout gouvernement, mais la formation immédiate d'un gouvernement meilleur.", Author = "Henry David Thoreau" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Ada_Ehi", Text = "Ne tente pas de te conformer à l'histoire de quelqu'un d'autre, car tu risquerais de priver le monde de la belle histoire que tu aurais pu être.", Author = "Ada Ehi" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Billy_the_Cat", Text = "[C'est] la goutte de lait qui fait déborder la soucoupe en quelque sorte!", Author = "Billy the Cat" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Bibata_Adamou_Dakaou", Text = "L’objectif est qu’il n’y ait plus jamais zéro femme admise mais un nombre important", Author = "Bibata Adamou Dakaou" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Gasandji_R%C3%AAver", Text = "Je tuerai, je tuerai, je tuerai le temps...", Author = "Gasandji Rêver" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Pascal_Quignard", Text = "Le seul lieu de l'espace où peuvent se rencontrer le lecteur et l'auteur est dans le point final.", Author = "Pascal Quignard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Bourgeon", Text = "Agnès: Puisque tu ne sembles rien ignorer de mon anatomie, il eût été mesquin de te présenter mon couteau revêtu de sa gaine!", Author = "François Bourgeon" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Fran%C3%A7ois_Goulard", Text = "Être ancien ministre, c'est s'asseoir à l'arrière d'une voiture et s'apercevoir qu'elle ne démarre pas.", Author = "François Goulard" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sidib%C3%A9_Dedeou_Ousmane", Text = "L’arme du syndicaliste, c’est la grève mais elle n’est pas toujours efficace à tout point de vue.", Author = "Sidibé Dedeou Ousmane" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Sophia_Loren", Text = "Les vêtements d'une femme devraient être comme une clôture barbelée: faire ce à quoi ils servent sans gêner la vue.", Author = "Sophia Loren" },
        new Quote { Id = "https://fr.wikiquote.org/wiki/Conseil_f%C3%A9d%C3%A9ral", Text = "Notre planète se rapproche des limites de ce qu’elle peut supporter. Les changements climatiques, la consommation excessive de ressources et la perte de biodiversité constituent des risques menaçant les fondements de notre vie.", Author = "Conseil fédéral" }
    };
}